package com.flovex.dshop;
import org.bukkit.Bukkit;import org.bukkit.Material;import org.bukkit.NamespacedKey;import org.bukkit.command.*;import org.bukkit.configuration.ConfigurationSection;import org.bukkit.configuration.file.YamlConfiguration;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.*;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.persistence.PersistentDataType;import org.bukkit.plugin.RegisteredServiceProvider;import org.bukkit.plugin.java.JavaPlugin;import java.io.File;import java.text.DecimalFormat;import java.util.*;
public final class SellManager implements Listener,CommandExecutor,TabCompleter{
 private final JavaPlugin plugin;private final NamespacedKey marker;private final File cfgFile,worthFile;private YamlConfiguration cfg,worth;private Object economy;private final Map<UUID,Double> totals=new HashMap<>();
 public SellManager(JavaPlugin p){plugin=p;marker=new NamespacedKey(p,"sell_gui");cfgFile=new File(p.getDataFolder(),"sell.yml");worthFile=new File(p.getDataFolder(),"worth.yml");if(!cfgFile.exists())p.saveResource("sell.yml",false);if(!worthFile.exists())p.saveResource("worth.yml",false);reload();setupEconomy();}
 public void register(){Bukkit.getPluginManager().registerEvents(this,plugin);PluginCommand c=plugin.getCommand("sell");if(c!=null){c.setExecutor(this);c.setTabCompleter(this);}}
 private void reload(){cfg=YamlConfiguration.loadConfiguration(cfgFile);worth=YamlConfiguration.loadConfiguration(worthFile);}
 private void setupEconomy(){try{if(Bukkit.getPluginManager().getPlugin("Vault")==null)return;Class<?> api=Class.forName("net.milkbowl.vault.economy.Economy");RegisteredServiceProvider<?> r=Bukkit.getServicesManager().getRegistration(api);if(r!=null)economy=r.getProvider();}catch(Exception|LinkageError e){plugin.getLogger().warning("Sell economy unavailable: "+e.getMessage());}}
 public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p)){s.sendMessage("Players only.");return true;}if(a.length>0&&a[0].equalsIgnoreCase("reload")){if(!p.hasPermission("dshop.admin")){p.sendMessage("§cNo permission.");return true;}reload();setupEconomy();p.sendMessage("§aSell settings reloaded.");return true;}if(a.length>0&&a[0].equalsIgnoreCase("top")){top(p);return true;}if(a.length>0&&a[0].equalsIgnoreCase("worth")){p.sendMessage("§bDshop Worth §8» §7Shop items sell for 50% of their shop price. Use /sell to preview.");return true;}open(p);return true;}
 private void open(Player p){Holder h=new Holder();Inventory inv=Bukkit.createInventory(h,54,col(cfg.getString("gui.title","&8Sell Items")));h.inv=inv;ItemStack[] contents=p.getInventory().getStorageContents();for(int i=0;i<Math.min(45,contents.length);i++)if(contents[i]!=null&&!contents[i].getType().isAir())inv.setItem(i,contents[i].clone());inv.setItem(49,button(Material.LIME_STAINED_GLASS_PANE,cfg.getString("gui.sell-name","&a&lSELL ITEMS"),List.of("&7Sell all sellable items in your inventory","&7Estimated total: &a$"+fmt(calc(p)),"","&e▸ Click to sell")));inv.setItem(53,button(Material.BARRIER,"&cClose",List.of("&7Close this menu")));p.openInventory(inv);}
 private ItemStack button(Material m,String n,List<String> lore){ItemStack i=new ItemStack(m);ItemMeta x=i.getItemMeta();x.setDisplayName(col(n));x.setLore(lore.stream().map(this::col).toList());x.getPersistentDataContainer().set(marker,PersistentDataType.BYTE,(byte)1);i.setItemMeta(x);return i;}
 private double value(Material m){String k=m.name();if(worth.contains("prices."+k))return worth.getDouble("prices."+k);double shop=shopHalf(m);if(shop>=0)return shop;return worth.getDouble("defaults."+k,0);}
 private double shopHalf(Material m){File dir=new File(plugin.getDataFolder(),"categories");File[] fs=dir.listFiles((d,n)->n.endsWith(".yml"));if(fs==null)return -1;for(File f:fs){YamlConfiguration y=YamlConfiguration.loadConfiguration(f);ConfigurationSection ps=y.getConfigurationSection("pages");if(ps==null)continue;for(String pg:ps.getKeys(false)){ConfigurationSection is=y.getConfigurationSection("pages."+pg+".items");if(is==null)continue;for(String id:is.getKeys(false))if(is.getString(id+".material","").equalsIgnoreCase(m.name())){double v=is.getDouble(id+".price",0);if(v>0)return v*.5;}}}return -1;}
 private boolean sellable(ItemStack i){return i!=null&&!i.getType().isAir()&&value(i.getType())>0;}
 private double calc(Player p){double n=0;for(ItemStack i:p.getInventory().getStorageContents())if(sellable(i))n+=value(i.getType())*i.getAmount();return n;}
 private boolean pay(Player p,double amount){if(economy==null)return false;try{for(var m:economy.getClass().getMethods()){if(!m.getName().equals("depositPlayer")||m.getParameterCount()!=2)continue;Class<?>[] t=m.getParameterTypes();if(t[0].isAssignableFrom(Player.class)&&(t[1]==double.class||t[1]==Double.class)){Object r=m.invoke(economy,p,amount);return r!=null&&Boolean.TRUE.equals(r.getClass().getMethod("transactionSuccess").invoke(r));}}}catch(Exception e){plugin.getLogger().warning("Sell payout failed: "+e.getMessage());}return false;}
 private void sell(Player p){ItemStack[] a=p.getInventory().getStorageContents();double sum=0;int count=0;for(int i=0;i<a.length;i++){ItemStack it=a[i];if(!sellable(it))continue;sum+=value(it.getType())*it.getAmount();count+=it.getAmount();a[i]=null;}if(count==0){p.sendMessage(col(cfg.getString("messages.nothing","&cNo sellable items.")));return;}if(!pay(p,sum)){p.sendMessage("§cSell failed: Vault economy is unavailable.");return;}p.getInventory().setStorageContents(a);totals.merge(p.getUniqueId(),sum,Double::sum);String msg=cfg.getString("messages.sold","&aSold &f{amount} &aitems for &f$ {total}.").replace("{amount}",String.valueOf(count)).replace("{total}",fmt(sum));p.sendMessage(col(msg));p.closeInventory();}
 private void top(Player p){p.sendMessage("§8§m-------- §bDshop Top Sellers §8§m--------");totals.entrySet().stream().sorted(Map.Entry.<UUID,Double>comparingByValue().reversed()).limit(10).forEach(e->{String n=Bukkit.getOfflinePlayer(e.getKey()).getName();p.sendMessage("§7"+(n==null?"Unknown":n)+" §8» §a$"+fmt(e.getValue()));});}
 private String fmt(double d){return new DecimalFormat("#,##0.##").format(d);}private String col(String s){return org.bukkit.ChatColor.translateAlternateColorCodes('&',s==null?"":s);}
 @EventHandler public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof Holder))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player p))return;if(e.getRawSlot()==49)sell(p);else if(e.getRawSlot()==53)p.closeInventory();}
 @EventHandler public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof Holder)e.setCancelled(true);}
 public List<String> onTabComplete(CommandSender s,Command c,String a,String[] args){return args.length==1?List.of("top","worth","reload"):List.of();}
 private static final class Holder implements InventoryHolder{Inventory inv;public Inventory getInventory(){return inv;}}
}